import { AnimatedSpriteNode, CharacterBody2DNode, Game, Input, Node } from 'cleo'
import { save, child, attribute, animAction, animParam, animTrigger } from 'cleo/decorators'

/**
 * Duskwell -- the player: the warrior of the Medieval Warrior pack. Attach to the `Player` Character Body 2D;
 * its children are `Sprite` (the animation set, whose state machine plays idle / run / jump / fall on its
 * own), `Sword` (the Area 2D the attack frames switch on) and, last, the `Player Controller` that reads Move
 * and Jump into the body's intent -- so the engine runs and jumps it, as a 3D Character's controller does.
 *
 * Everything that makes it THIS game's warrior is here, the way the 3D examples add a roll or a sprint over
 * the engine's walking:
 *   * the moves a metroidvania hands out -- a double jump, a dash, a wall slide and wall jump -- each off
 *     until its pickup (`hasDoubleJump`, `hasDash`, `hasWallJump`), and a jump cut (let go early for a hop).
 *     They run in `onMove2D`, every physics substep, so a dash covers the same distance at any frame rate.
 *   * a three-hit combo on Attack -- press again during a swing, or just after it, for the next.
 *   * health, a hurt knock-back with a moment of invulnerability, death, and a respawn at the last lamp.
 * Pickups call `collect(kind)`; checkpoints call `setRespawn(x, y)`.
 *
 * Anything that hurts on touch has an Area 2D that sees the player's layer, under a node with a
 * `contactDamage` field (a bat's `Bite`, a guard's `Blade`). Falling below `killY` costs the whole health.
 */
export default class DuskPlayer extends CharacterBody2DNode {
  @attribute
  public maxHealth: number = 5
  @attribute
  public health: number = 5
  @save
  @attribute
  public diamonds: number = 0
  /** Seconds of invulnerability after a hit, the sprite flickering. */
  @attribute
  public invulnerableSeconds: number = 1.1
  /** Seconds the controls are taken away by a hit. */
  @attribute
  public hurtSeconds: number = 0.3
  /** The knock-back of a hit: away, and up. */
  @attribute
  public knockback: number = 9
  @attribute
  public knockup: number = 7
  /** Running speed while a swing is on: a swing commits. */
  @attribute
  public attackRunSpeed: number = 1.5
  /** Seconds after a swing ends in which a press still chains the next one. */
  @attribute
  public comboWindow: number = 0.35
  @attribute
  public attackAction: string = 'Attack'
  @attribute
  public jumpAction: string = 'Jump'
  @attribute
  public dashAction: string = 'Dash'
  /** Below this the player has fallen out of the world (the map's bottom edge is y = 0). */
  @attribute
  public killY: number = -4
  /** Seconds the death plays before the respawn. */
  @attribute
  public deathSeconds: number = 1.8

  // --- the moves, found over the game (kept by a save) ---------------------------------------------------
  @save
  @attribute('Moves')
  public hasDoubleJump: boolean = false
  @save
  @attribute('Moves')
  public hasDash: boolean = false
  @save
  @attribute('Moves')
  public hasWallJump: boolean = false
  /** Jumps in the air before landing again, with the double jump, and their height as a share of a jump's. */
  @attribute('Moves')
  public airJumps: number = 1
  @attribute('Moves')
  public airJumpHeight: number = 0.85
  /** Letting go of jump while still rising keeps this share of the speed: a tap is a hop. */
  @attribute('Moves')
  public jumpCut: number = 0.45
  /** The dash: speed, seconds, seconds before the next, and dashes in the air before landing. */
  @attribute('Moves')
  public dashSpeed: number = 22
  @attribute('Moves')
  public dashTime: number = 0.2
  @attribute('Moves')
  public dashCooldown: number = 0.35
  @attribute('Moves')
  public airDashes: number = 1
  /** The fastest slide down a wall pressed into; a wall jump's push away and up; seconds the push holds. */
  @attribute('Moves')
  public wallSlideSpeed: number = 3
  @attribute('Moves')
  public wallJumpX: number = 9
  @attribute('Moves')
  public wallJumpY: number = 12
  @attribute('Moves')
  public wallJumpLock: number = 0.16

  @child('Sprite')
  private _sprite: AnimatedSpriteNode = null
  private _baseWalk: number = 8
  private _baseMaxFall: number = 24
  /** The swing of the combo on now or last (1..3), 0 when the combo is over. */
  private _combo: number = 0
  private _swinging: boolean = false
  private _queued: boolean = false
  private _graceLeft: number = 0
  private _hurtLeft: number = 0
  private _invulnLeft: number = 0
  private _dead: boolean = false
  private _deathLeft: number = 0
  /** The last lamp's spot: where a death, and a loaded game, put the player. */
  @save
  private _respawn: [number, number] = [0, 0]
  private _touching: Node[] = []
  private _notice: string = ''
  private _noticeAge: number = 99
  // The moves' memory, kept per substep in onMove2D.
  private _jumpHeld: boolean = false
  private _dashPress: number = 0
  private _airJumpsLeft: number = 0
  private _airDashesLeft: number = 0
  private _dashLeft: number = 0
  private _dashDir: number = 1
  private _dashCooldownLeft: number = 0
  private _wallLockLeft: number = 0
  private _wallLockDir: number = 0
  private _rising: boolean = false
  private _engineJumpSeen: boolean = false
  private _wallSliding: boolean = false

  onStart() {
    this._baseWalk = this.walkSpeed
    this._baseMaxFall = this.maxFallSpeed
    // A loaded game starts at the last lamp the save knew (`_respawn` is @save); a new one where the
    // player stands, which is then the first respawn point.
    if (this.wasRestored) {
      this.teleport(this._respawn[0], this._respawn[1])
      const cam = this.findNode('Camera') as any
      cam?.snapToTarget?.()
    } else {
      this._respawn = [this.position[0], this.position[1]]
    }
    this.health = this.maxHealth
  }

  /** The one-line message the HUD shows (a pickup, a checkpoint), and how long ago it came. */
  public get notice(): string { return this._noticeAge < 3 ? this._notice : '' }
  public get isDead(): boolean { return this._dead }
  public get isDashing(): boolean { return this._dashLeft > 0 }
  public get isWallSliding(): boolean { return this._wallSliding }

  public say(text: string) { this._notice = text; this._noticeAge = 0 }

  /**
   * Once a frame, after the Player Controller wrote this frame's intent and before the 2D physics moves the
   * body: read this game's own buttons, and take the controls away while hurt or dead.
   */
  onUpdate(delta: number) {
    this._noticeAge += delta
    this._jumpHeld = Input.pressed(this.jumpAction)
    if (Input.started(this.dashAction)) this._dashPress = 0.12
    if (this._dead) {
      this._deathLeft -= delta
      this._lockControls()
      if (this._deathLeft <= 0) this.respawn()
      return
    }
    this._invulnLeft = Math.max(0, this._invulnLeft - delta)
    if (this._hurtLeft > 0) {
      this._hurtLeft -= delta
      this._lockControls()
    }
    if (this._sprite) this._sprite.opacity = this._invulnLeft > 0 && Math.floor(this._invulnLeft * 16) % 2 === 0 ? 0.35 : 1

    if (this._graceLeft > 0) {
      this._graceLeft -= delta
      if (this._graceLeft <= 0) this._combo = 0
    }
    if (Input.started(this.attackAction) && this._hurtLeft <= 0) this._attack()
    this.walkSpeed = this._swinging && this.isGrounded ? this.attackRunSpeed : this._baseWalk

    // Whatever hurts on touch, while it still touches (a hit does nothing while invulnerable).
    for (const n of this._touching) {
      const owner = (n.parent as any) ?? null
      const damage = (owner?.contactDamage ?? (n as any).contactDamage ?? 0) as number
      if (damage > 0 && !owner?.isDead) this.takeHit(damage, n)
    }
    if (this.position[1] < this.killY) this.takeHit(this.maxHealth, null)
  }

  /** No steering and no jumps: the knock-back or the fall plays out. */
  private _lockControls() {
    const intent = this.drive()
    intent.move[0] = 0
    intent.move[1] = 0
    intent.requests.jump = 0
    this._dashPress = 0
  }

  /**
   * Every physics substep, before the engine steers: this game's moves. Returning true owns the substep --
   * the engine's running and jumping skip it -- which is what a dash, a knock-back and a death do.
   */
  onMove2D(dt: number, _substep: number): boolean {
    const v = this.velocity2D
    const grounded = this.isGrounded
    // Landing refills what the air spends.
    if (grounded) {
      this._airJumpsLeft = this.hasDoubleJump ? Math.max(0, Math.floor(this.airJumps)) : 0
      this._airDashesLeft = Math.max(0, Math.floor(this.airDashes))
      this._rising = false
    }
    this._dashCooldownLeft = Math.max(0, this._dashCooldownLeft - dt)
    this._wallLockLeft = Math.max(0, this._wallLockLeft - dt)
    this._dashPress = Math.max(0, this._dashPress - dt)

    // Hurt or dead: the knock-back's arc, slowed along the ground.
    if (this._dead || this._hurtLeft > 0) {
      if (grounded) v[0] = this._toward(v[0], 0, this.deceleration * dt)
      return true
    }

    const steer = this.intent.move[0]
    // --- the dash: a straight burst that holds its height and ends early on a wall ------------------------
    if (this._dashPress > 0 && this.hasDash && this._dashLeft <= 0 && this._dashCooldownLeft <= 0
        && (grounded || this._airDashesLeft > 0)) {
      if (!grounded) this._airDashesLeft--
      this._dashPress = 0
      this._dashLeft = this.dashTime
      this._dashDir = steer > 0.2 ? 1 : steer < -0.2 ? -1 : this.facing
      this.facing = this._dashDir
      this._dashCooldownLeft = this.dashCooldown
      this._rising = false
      this.gravityScale = 0
      this._dashed()
    }
    if (this._dashLeft > 0) {
      this._dashLeft = Math.max(0, this._dashLeft - dt)
      if (this._dashDir > 0 ? this.contacts.wallRight : this.contacts.wallLeft) this._dashLeft = 0
      v[0] = this._dashLeft > 0 ? this._dashDir * this.dashSpeed : this._dashDir * this._baseWalk
      v[1] = 0
      if (this._dashLeft <= 0) this.gravityScale = 1
      this._dashing = this._dashLeft > 0
      return true
    }

    // Just after a wall jump, steering back into that wall is ignored: the push away has to land first.
    if (this._wallLockLeft > 0 && Math.sign(steer) === this._wallLockDir) this.drive().move[0] = 0

    // --- the wall slide: pressing into a wall while falling ------------------------------------------
    const pressing = (steer > 0.2 && this.contacts.wallRight) || (steer < -0.2 && this.contacts.wallLeft)
    this._wallSliding = this.hasWallJump && !grounded && pressing && v[1] <= 0
    this.maxFallSpeed = this._wallSliding ? this.wallSlideSpeed : this._baseMaxFall
    this._slidingParam = this._wallSliding

    // --- the jumps the engine does not make: off a wall, and in the air --------------------------------
    if (this.jumpRequested && !this.canJump) {
      const wall = this.onWall
      if (this.hasWallJump && wall !== 0) {
        this.consumeJump()
        const away = -wall
        v[0] = away * this.wallJumpX
        v[1] = this.wallJumpY
        this.facing = away
        this._wallLockLeft = this.wallJumpLock
        this._wallLockDir = -away
        this._rising = true
        this._wallSliding = false
        this.drive().move[0] = 0
        this._jumped()
      } else if (this._airJumpsLeft > 0) {
        this.consumeJump()
        this._airJumpsLeft--
        v[1] = this.jumpSpeed * Math.sqrt(Math.max(0, this.airJumpHeight))
        this._rising = true
        this._jumped()
      }
    }
    // The engine's own jump, from the ground, is a rise too (seen once: the flag holds for the frame).
    if (this.justJumped) {
      if (!this._engineJumpSeen && v[1] > 0) this._rising = true
      this._engineJumpSeen = true
    } else this._engineJumpSeen = false

    // Letting go while rising cuts the jump: the height follows how long it is held.
    if (this._rising && !this._jumpHeld && v[1] > 0) {
      v[1] *= this.jumpCut
      this._rising = false
    }
    if (v[1] <= 0) this._rising = false
    return false
  }

  private _toward(current: number, target: number, step: number): number {
    return current < target ? Math.min(target, current + step) : Math.max(target, current - step)
  }

  private _attack() {
    if (!this._sprite) return
    // A press during a swing chains the next one when this one ends.
    if (this._swinging) {
      if (this._combo < 3) this._queued = true
      return
    }
    // Just after one, it chains at once; otherwise the combo starts over.
    this._swing(this._graceLeft > 0 && this._combo < 3 ? this._combo + 1 : 1)
  }

  private _swing(n: number) {
    this._combo = n
    this._swinging = true
    this._queued = false
    this._graceLeft = 0
    this._swingClip(n)
  }

  // ----- the sprite: commands sent down to it (animator:*), never a call on it ------------------------

  /** The sprite machine's `dashed` trigger. */
  @animTrigger('dashed')
  private _dashed(): void {}

  /** The sprite machine's `jumped` trigger: a wall jump, an air jump. */
  @animTrigger('jumped')
  private _jumped(): void {}

  /** The sprite machine's `dashing` and `wallSliding`: only a change is sent, however often they are set. */
  @animParam('dashing')
  private _dashing: boolean = false
  @animParam('wallSliding')
  private _slidingParam: boolean = false

  /** Swing `n` of the combo: its clip, played from the start. */
  @animAction()
  private _swingClip(n: number) {
    return { clip: 'attack' + n, restart: true }
  }

  @animAction('hurt', { restart: true })
  private _hurtClip(): void {}

  @animAction('death', { restart: true })
  private _deathClip(): void {}

  /** Back on its state machine after a clip it was told to play. */
  private _resume(): void {
    this.dispatchDown('animator:Resume')
  }

  private _endCombo() {
    this._combo = 0
    this._swinging = false
    this._queued = false
    this._graceLeft = 0
  }

  onAnimationFinished(clip: string) {
    if (clip === 'hurt' && !this._dead) this._resume()
    if (!clip.startsWith('attack') || !this._swinging) return
    this._swinging = false
    if (this._queued && this._combo < 3) this._swing(this._combo + 1)
    else if (this._combo < 3) this._graceLeft = this.comboWindow
    else this._endCombo()
  }

  onTriggerEnter(other: Node) {
    if (!this._touching.includes(other)) this._touching.push(other)
  }

  onTriggerExit(other: Node) {
    const i = this._touching.indexOf(other)
    if (i >= 0) this._touching.splice(i, 1)
  }

  /** A hit for `damage` from `from` (or the world): knock-back, invulnerability, or death. */
  public takeHit(damage: number, from: Node | null) {
    if (this._dead || this._invulnLeft > 0) return
    this.health = Math.max(0, this.health - damage)
    const cam = this.findNode('Camera') as any
    cam?.shake?.(0.25, 0.25)
    Game.hitStop(0.06)
    this._endCombo()
    this._dashLeft = 0
    this.gravityScale = 1
    if (this.health <= 0) { this._die(); return }
    this._invulnLeft = this.invulnerableSeconds
    this._hurtLeft = this.hurtSeconds
    const away = from ? Math.sign(this.worldPosition[0] - from.worldPosition[0]) || -this.facing : -this.facing
    this.velocity2D[0] = away * this.knockback
    this.velocity2D[1] = this.knockup
    this._hurtClip()
  }

  private _die() {
    this._dead = true
    this._deathLeft = this.deathSeconds
    this._deathClip()
  }

  /** Back at the last checkpoint, whole. */
  public respawn() {
    this._dead = false
    this._hurtLeft = 0
    this.health = this.maxHealth
    this._invulnLeft = this.invulnerableSeconds
    this.teleport(this._respawn[0], this._respawn[1])
    this._resume()
    const cam = this.findNode('Camera') as any
    cam?.snapToTarget?.()
  }

  public setRespawn(x: number, y: number) {
    this._respawn = [x, y]
  }

  public heal(amount: number) {
    this.health = Math.min(this.maxHealth, this.health + amount)
  }

  /** A pickup: a diamond, a heart, or one of the movement abilities. */
  public collect(kind: string, amount: number = 1) {
    if (kind === 'diamond') { this.diamonds += amount; return }
    if (kind === 'heart') { this.heal(amount); this.say('Health restored'); return }
    if (kind === 'dash') { this.hasDash = true; this.say('Dash: Shift or L'); return }
    if (kind === 'doubleJump') { this.hasDoubleJump = true; this.say('Double jump: jump again in the air'); return }
    if (kind === 'wallJump') { this.hasWallJump = true; this.say('Wall jump: hold toward a wall, then jump'); return }
  }
}

import { AnimatedSpriteNode, CharacterBody2DNode, ControllerNode, Node, TriggerNode } from 'cleo'
import { find, child, attribute, animAction, eventListener } from 'cleo/decorators'

/**
 * Duskwell -- a bat. Attach to a flying Character Body 2D (no gravity, through one-way platforms) whose
 * children are `Sprite` (the bat's clips: sleep, wakeup, fly, attack, hurt, die), `Bite` (an Area 2D that
 * sees the player's layer: the player's script asks this node's `contactDamage`) and, last, its `Bat Brain`
 * AI Controller.
 *
 * The brain decides (the Bat Brain asset): asleep until it sees the player, it wakes, flies at the player
 * on the air grid -- round the pillar, not through it --, swoops when close, and flies home to roost when
 * it forgets the player. This script does what a goal cannot: waking, the swoop (a dash it owns in
 * onMove2D), the hurt and the death, and it publishes what the brain reads: `isAwake`, `swoopReady`,
 * `isSwooping`, `isHurt`, `isDead`, `distanceFromHome`.
 */
export default class DuskBat extends CharacterBody2DNode {
  @attribute
  public health: number = 3
  @attribute
  public contactDamage: number = 1
  @attribute
  public swoopSpeed: number = 7.5
  /** Seconds between swoops. */
  @attribute
  public swoopCooldown: number = 1.2
  @attribute
  public knockback: number = 8
  /** The bat's art faces left: its sprite is mirrored to face right. */
  @attribute
  public artFacesLeft: boolean = false

  @child('Sprite')
  private _sprite: AnimatedSpriteNode = null
  @child('Bite')
  private _bite: TriggerNode = null
  private _brain: ControllerNode = null
  @find('Player')
  private _player: Node = null
  private _home: [number, number] = [0, 0]
  private _awake: boolean = false
  private _waking: boolean = false
  private _swoopLeft: number = 0
  private _swoopDir: [number, number] = [1, 0]
  private _cooldownLeft: number = 0
  private _hurtLeft: number = 0
  private _dead: boolean = false
  private _deadLeft: number = 0
  private _bob: number = 0

  onStart() {
    this._brain = this.children.find(c => c instanceof ControllerNode) as ControllerNode ?? null
    this.movement = 'fly'
    this.oneWayPlatforms = false
    this.flipSprites = false
    const p = this.position
    // A flier steers by the middle of its box: home, for Roost's 'point', is there too.
    this._home = [p[0], p[1] + this.size[1] * 0.5]
    if (this._brain) this._brain.goalPoint = [this._home[0], this._home[1], 0]
    this._bob = Math.random() * 6.28
    this._clip('sleep')
  }

  /** Play `name` on the sprite from its start: `animator:PlayAction`, sent down to it. */
  @animAction()
  private _clip(name: string) {
    return { clip: name, restart: true }
  }

  /** Awake once the wake-up has played out (the sprite says so with `animation:ClipFinished`): off it flies. */
  @eventListener('animation:ClipFinished', { where: { clip: 'wakeup' } })
  private _wokeUp() {
    if (!this._waking || this._awake || this._dead) return
    this._awake = true
    this._clip('fly')
  }

  public get isDead(): boolean { return this._dead }
  public get isHurt(): boolean { return this._hurtLeft > 0 }
  public get isAwake(): boolean { return this._awake }
  public get isSwooping(): boolean { return this._swoopLeft > 0 }
  public get swoopReady(): boolean { return this._awake && this._swoopLeft <= 0 && this._cooldownLeft <= 0 && !this._dead }
  public get distanceFromHome(): number {
    return Math.hypot(this.position[0] - this._home[0], this.position[1] + this.size[1] * 0.5 - this._home[1])
  }

  onUpdate(delta: number) {
    this._cooldownLeft = Math.max(0, this._cooldownLeft - delta)
    this._hurtLeft = Math.max(0, this._hurtLeft - delta)
    this._bob += delta * 5
    if (this._dead) {
      this._deadLeft -= delta
      if (this._deadLeft <= 0) this.remove()
      return
    }
    const state = this._brain?.behaviorState ?? ''
    const s = this._sprite
    if (state === 'Sleep') {
      this._awake = false
      this._waking = false
      if (s && s.clip !== 'sleep') this._clip('sleep')
    } else if (state === 'Wake') {
      // The wake-up plays once; `_wokeUp` hears it finish.
      if (!this._waking) { this._waking = true; this._clip('wakeup') }
    } else if (state === 'Swoop') {
      if (this.swoopReady) this._startSwoop()
    } else if ((state === 'Chase' || state === 'Roost') && s && s.clip !== 'fly' && this._swoopLeft <= 0 && this._hurtLeft <= 0) {
      this._clip('fly')
    }
    // A gentle bob, on the sprite alone so the body's path stays true.
    if (s) s.setPosition([0, this._awake ? Math.sin(this._bob) * 0.12 : 0, 0])
    // Face the way it flies, or the player.
    const vx = this.velocity2D[0]
    const p = this._player
    const facingLeft = (Math.abs(vx) > 0.1 ? vx : p ? p.worldPosition[0] - this.worldPosition[0] : 1) < 0
    if (s) s.flipX = this.artFacesLeft ? !facingLeft : facingLeft
  }

  private _startSwoop() {
    const p = this._player
    if (!p) return
    const dx = p.worldPosition[0] - this.worldPosition[0]
    const dy = p.worldPosition[1] + 1.2 - (this.worldPosition[1] + this.size[1] * 0.5)
    const d = Math.hypot(dx, dy) || 1
    this._swoopDir = [dx / d, dy / d]
    this._swoopLeft = 0.55
    this._cooldownLeft = this.swoopCooldown
    this._clip('attack')
  }

  /**
   * The swoop, the hurt and the death are the bat's own motion, every physics substep: a wind-up back, a
   * lunge at the player; a knock-back easing off; a fall out of the air.
   */
  onMove2D(dt: number): boolean {
    const v = this.velocity2D
    if (this._dead) {
      v[0] *= Math.pow(0.4, dt)
      v[1] = Math.max(-14, v[1] - 30 * dt)
      return true
    }
    if (this._hurtLeft > 0) {
      const k = Math.pow(0.02, dt)
      v[0] *= k; v[1] *= k
      return true
    }
    if (this._swoopLeft > 0) {
      const t = 0.55 - this._swoopLeft
      this._swoopLeft = Math.max(0, this._swoopLeft - dt)
      const speed = t < 0.15 ? -2 : this.swoopSpeed
      v[0] = this._swoopDir[0] * speed
      v[1] = this._swoopDir[1] * speed
      return true
    }
    return false
  }

  onTriggerEnter(other: Node) {
    if (other.name !== 'Sword' || this._dead) return
    this.takeHit(1, other)
  }

  public takeHit(damage: number, from: Node | null) {
    if (this._dead) return
    this.health -= damage
    const away = from ? Math.sign(this.worldPosition[0] - from.worldPosition[0]) || 1 : 1
    this.velocity2D[0] = away * this.knockback
    this.velocity2D[1] = 3
    this._swoopLeft = 0
    this._awake = true
    const cam = this.findNode('Camera') as any
    cam?.shake?.(0.12, 0.15)
    if (this.health <= 0) {
      this._dead = true
      if (this._bite) this._bite.enabled = false
      this._deadLeft = 1.4
      this._clip('die')
      ;(this._player as any)?.collect?.('diamond', 1)
      return
    }
    this._hurtLeft = 0.35
    this._clip('hurt')
  }
}

import { AnimatedSpriteNode, CharacterBody2DNode, ControllerNode, Node } from 'cleo'
import { find, child, attribute, animAction } from 'cleo/decorators'

/**
 * Duskwell -- a Ruin Guard: the knight of the Pixel Platformer set, gone dark. Attach to a walking
 * Character Body 2D whose children are `Sprite` (the knight's clips, its state machine playing idle / run /
 * jump / fall / land from the body), `Blade` (an Area 2D the attack frames switch on) and, last, its `Guard
 * Brain` AI Controller.
 *
 * The brain decides what the guard does (the Guard Brain asset): walk its route, chase the player it sees
 * across the 2D navigation -- jumping between platforms where the path says --, attack when close and
 * level, search where it lost the player, walk home. This script does what a goal cannot: the swing, the
 * hurt and the death, and it publishes the facts the brain reads, as fields: `attackReady`, `isAttacking`,
 * `isHurt`, `isDead`, `targetDead`, `distanceFromHome`.
 *
 * The player's script reads `contactDamage` from the Blade's owner, so the Blade hurts the player while
 * the swing has it switched on.
 */
export default class DuskGuard extends CharacterBody2DNode {
  @attribute
  public maxHealth: number = 3
  @attribute
  public health: number = 3
  @attribute
  public contactDamage: number = 1
  /** Seconds between swings. */
  @attribute
  public attackCooldown: number = 1.1
  /** A sword hit's push away, and up. */
  @attribute
  public knockback: number = 7
  @attribute
  public knockup: number = 4
  /** Seconds a hit staggers it. */
  @attribute
  public hurtSeconds: number = 0.35
  /** Diamonds it drops. */
  @attribute
  public reward: number = 2

  @child('Sprite')
  private _sprite: AnimatedSpriteNode = null
  private _brain: ControllerNode = null
  @find('Player')
  private _player: Node = null
  private _home: [number, number] = [0, 0]
  private _attacking: boolean = false
  private _attackLeft: number = 0
  private _cooldownLeft: number = 0
  private _hurtLeft: number = 0
  private _dead: boolean = false
  private _deadLeft: number = 0

  onStart() {
    this._brain = this.children.find(c => c instanceof ControllerNode) as ControllerNode ?? null
    this._home = [this.position[0], this.position[1]]
    // Where Return walks back to: the brain's goal point, read when a state targets 'point'.
    if (this._brain) this._brain.goalPoint = [this._home[0], this._home[1], 0]
    this.health = this.maxHealth
  }

  public get attackReady(): boolean { return !this._attacking && this._cooldownLeft <= 0 && this.isGrounded && !this._dead }
  public get isAttacking(): boolean { return this._attacking }
  public get isHurt(): boolean { return this._hurtLeft > 0 }
  public get isDead(): boolean { return this._dead }
  public get targetDead(): boolean { return (this._player as any)?.isDead === true }
  public get distanceFromHome(): number {
    return Math.hypot(this.position[0] - this._home[0], this.position[1] - this._home[1])
  }

  onUpdate(delta: number) {
    this._cooldownLeft = Math.max(0, this._cooldownLeft - delta)
    this._hurtLeft = Math.max(0, this._hurtLeft - delta)
    if (this._sprite) this._sprite.opacity = this._hurtLeft > 0 && Math.floor(this._hurtLeft * 20) % 2 === 0 ? 0.4 : 1
    if (this._dead) {
      this._deadLeft -= delta
      if (this._deadLeft <= 0) this.remove()
      return
    }
    if (this._attacking) {
      this._attackLeft -= delta
      if (this._attackLeft <= 0) this._attacking = false
    }
    // The brain's Attack state is the cue; the swing is ours.
    if (this._brain?.behaviorState === 'Attack' && this.attackReady) this._swing()
  }

  private _swing() {
    const p = this._player
    if (p) this.facing = p.worldPosition[0] - this.worldPosition[0]
    this._attacking = true
    this._attackLeft = 0.75
    this._cooldownLeft = this.attackCooldown
    this._attackClip()
  }

  // ----- the sprite: commands sent down to it (animator:*), never a call on it ------------------------

  @animAction('attack', { restart: true })
  private _attackClip(): void {}

  @animAction('dead', { restart: true })
  private _deadClip(): void {}

  onAnimationFinished(clip: string) {
    if (clip === 'attack') {
      this._attacking = false
      // Back on the sprite's state machine (idle, run).
      this.dispatchDown('animator:Resume')
    }
  }

  /** A hurt or dead guard's motion is its own: the knock-back's arc, slowed along the ground. */
  onMove2D(dt: number): boolean {
    if (this._hurtLeft <= 0 && !this._dead) return false
    if (this.isGrounded) {
      const v = this.velocity2D
      const step = this.deceleration * dt
      v[0] = v[0] > 0 ? Math.max(0, v[0] - step) : Math.min(0, v[0] + step)
    }
    return true
  }

  onTriggerEnter(other: Node) {
    if (other.name === 'Sword' && !this._dead) this.takeHit(1, other)
  }

  public takeHit(damage: number, from: Node | null) {
    if (this._dead) return
    this.health -= damage
    const away = from ? Math.sign(this.worldPosition[0] - from.worldPosition[0]) || 1 : 1
    this.velocity2D[0] = away * this.knockback
    this.velocity2D[1] = this.knockup
    this._attacking = false
    this._hurtLeft = this.hurtSeconds
    const cam = this.findNode('Camera') as any
    cam?.shake?.(0.12, 0.15)
    if (this.health > 0) return
    this._dead = true
    this._deadLeft = 1.6
    this._deadClip()
    const blade = this.getChildByName('Blade')[0] as any
    if (blade) blade.enabled = false
    ;(this._player as any)?.collect?.('diamond', this.reward)
  }
}

import { Node, TriggerNode } from 'cleo'
import { attribute } from 'cleo/decorators'

/**
 * Duskwell -- something lying in the world for the player to take. Attach to an Area 2D that sees the
 * player's layer; its children are the visuals (a sprite), which bob.
 *
 *   kind = 'diamond'     +`amount` diamonds
 *   kind = 'heart'       heals `amount`
 *   kind = 'dash' | 'doubleJump' | 'wallJump'   a movement ability, for good
 *
 * The player decides what a kind does (DuskPlayer.collect); this only hands it over and goes.
 */
export default class DuskPickup extends TriggerNode {
  @attribute
  public kind: string = 'diamond'
  @attribute
  public amount: number = 1
  @attribute
  public bobHeight: number = 0.12
  @attribute
  public bobSpeed: number = 3

  private _time: number = 0
  private _taken: boolean = false
  private _base: number[] = []

  onStart() {
    this._time = (this.worldPosition[0] * 0.37) % 6.28
    this._base = this.children.map(c => c.position[1])
  }

  onUpdate(delta: number) {
    this._time += delta * this.bobSpeed
    const y = Math.sin(this._time) * this.bobHeight
    this.children.forEach((c, i) => {
      if (this._base[i] === undefined) return
      const p = c.position
      c.setPosition([p[0], this._base[i] + y, p[2]])
    })
  }

  onTriggerEnter(other: Node) {
    if (this._taken || typeof (other as any).collect !== 'function') return
    this._taken = true
    ;(other as any).collect(this.kind, this.amount)
    this.enabled = false
    this.remove()
  }
}

import { AnimatedSpriteNode, Logger, Node, SaveGame, TriggerNode } from 'cleo'
import { save, child, attribute } from 'cleo/decorators'

/**
 * Duskwell -- a checkpoint: a lamp the player lights by walking past it. Attach to an Area 2D that sees the
 * player's layer; its `Lamp` child is the sprite, dim until lit. Lighting it heals the player and makes it
 * where the player comes back after a death.
 *
 * Every lamp the player reaches saves the game to the `auto` slot (SaveGame): the diamonds and moves the
 * player carries, the lamps lit, the pickups taken. The title screen's Continue loads it.
 */
export default class DuskCheckpoint extends TriggerNode {
  @attribute
  public litTint: number[] = [1, 1, 1]
  @attribute
  public unlitTint: number[] = [0.35, 0.35, 0.45]
  @attribute
  public healTo: number = 99

  /** Whether the lamp is lit: a loaded game keeps it lit. */

  @save
  private _lit: boolean = false
  @child('Lamp')
  private _lamp: AnimatedSpriteNode = null

  onStart() {
    // A lamp lit before a save comes back lit (the field is @save).
    if (this._lamp) this._lamp.tint = (this._lit ? this.litTint : this.unlitTint) as [number, number, number]
  }

  onTriggerEnter(other: Node) {
    const p = other as any
    if (typeof p.setRespawn !== 'function') return
    const here = this.worldPosition
    p.setRespawn(here[0], here[1] - this.size[1] / 2 + 0.01)
    p.heal?.(this.healTo)
    if (!this._lit) {
      this._lit = true
      if (this._lamp) this._lamp.tint = this.litTint as [number, number, number]
      p.say?.('Checkpoint')
    }
    this._save()
  }

  /** The checkpoint save. Only where the game can save (it cannot in a test with no store, say). */
  private _save() {
    if (!SaveGame.available) return
    SaveGame.save('auto', { label: this.name })
      .catch(e => Logger.warn(`The checkpoint could not save: ${e?.message ?? e}`, 'Script'))
  }
}

import { Node, UIRootNode, UITextNode } from 'cleo'
import { child, attribute } from 'cleo/decorators'

/**
 * Duskwell -- the HUD. Attach to the `HUD` screen-space UI Root; it reads the `Player` node every frame and
 * writes its widgets, found by name once:
 *
 *   Health     uiText   "HP 4 / 5"
 *   Diamonds   uiText   the diamonds carried
 *   Notice     uiText   the player's one-line message (a pickup, a checkpoint), empty otherwise
 */
export default class DuskHud extends UIRootNode {
  @attribute
  public playerName: string = 'Player'

  private _player: Node = null
  @child('Health')
  private _health: UITextNode = null
  @child('Diamonds')
  private _diamonds: UITextNode = null
  @child('Notice')
  private _notice: UITextNode = null

  onStart() {
    this._player = this.findNode(this.playerName) ?? null
  }

  onUpdate() {
    const p = this._player as any
    if (!p) return
    const health = `HP ${Math.max(0, Math.ceil(p.health ?? 0))} / ${p.maxHealth ?? 0}`
    if (this._health && this._health.text !== health) this._health.text = health
    const diamonds = `Diamonds ${p.diamonds ?? 0}`
    if (this._diamonds && this._diamonds.text !== diamonds) this._diamonds.text = diamonds
    const notice = p.notice ?? ''
    if (this._notice && this._notice.text !== notice) this._notice.text = notice
  }
}

import { Game, Input, Logger, Node, SaveGame, UIButtonNode, UIRootNode } from 'cleo'
import { attribute } from 'cleo/decorators'

/**
 * Duskwell -- the title screen. Attach to the `Title` screen-space UI Root, authored hidden:
 *
 *   Backdrop
 *     Card
 *       Heading     "Duskwell"                              uiText
 *       Continue    loads the last checkpoint's save        uiButton
 *       New Game    starts again from the beginning         uiButton
 *       Hint        the keys                                uiText
 *
 * It shows only when there is a save to go back to and this session did not come from one: a first game
 * goes straight in, and so does one the title already let through (the `started` global, kept in every
 * save). While it shows the game is paused. Jump picks Continue and Dash picks New Game, or click.
 *
 * It listens in a LATE UPDATE, which runs every frame paused or not: no node's onUpdate runs while paused.
 */
export default class DuskTitle extends UIRootNode {
  /** The slot Continue loads: the one the checkpoints save to. */
  @attribute
  public slot: string = 'auto'
  @attribute
  public continueAction: string = 'Jump'
  @attribute
  public newGameAction: string = 'Dash'
  @attribute
  public isOpen: boolean = false

  private _stopListening: (() => void) | null = null

  async onStart() {
    this.visible = false
    this.isOpen = false
    const resume = this._find('Continue') as UIButtonNode
    if (resume) resume.onPress = () => this._continue()
    const fresh = this._find('New Game') as UIButtonNode
    if (fresh) fresh.onPress = () => this._newGame()
    this._stopListening = this.scene?.addLateUpdate(() => this._listen()) ?? null

    // Loaded (Continue, or the editor's Play from save), already past this screen, or nowhere to save to.
    if (!SaveGame.available || SaveGame.loadedFrom || SaveGame.has('started')) return
    let saved = false
    try { saved = await SaveGame.exists(this.slot) } catch { saved = false }
    if (!saved) { SaveGame.set('started', true); return }
    this.open()
  }

  onDespawn() {
    this._stopListening?.()
    this._stopListening = null
  }

  public open(): void {
    this.isOpen = true
    this.visible = true
    Game.pause()
    Input.releaseMouse()
  }

  public close(): void {
    if (!this.isOpen) return
    this.isOpen = false
    this.visible = false
    Game.resume()
  }

  private _listen(): void {
    if (!this.isOpen) return
    if (Input.started(this.continueAction)) this._continue()
    else if (Input.started(this.newGameAction)) this._newGame()
  }

  private _continue(): void {
    this.close()
    SaveGame.load(this.slot, { loadingScreen: { title: 'Duskwell' } })
      .catch(e => Logger.warn(`Continue: ${e?.message ?? e}`, 'Script'))
  }

  private _newGame(): void {
    // The lamps, pickups and moves of the last game stay in its save (slot `auto`) until a lamp saves over it.
    SaveGame.newGame()
    SaveGame.set('started', true)
    this.close()
  }

  private _find(name: string, under: Node = this): Node {
    for (const child of under.children) {
      if (child.name === name) return child
      const deeper = this._find(name, child)
      if (deeper) return deeper
    }
    return null
  }
}
